import os

COLLECTION_NAME = os.environ.get("COLLECTION_NAME","high_risk_profiles")


def vector_search(embedding, k=5, projection=None):
    """Run a server-side vector search using DocumentDB $search / cosmosSearch operator.
    Returns list of (doc, score).
    """
    db = get_db()
    coll = db[COLLECTION_NAME]
    pipeline = [
        {
            "$search": {
                "cosmosSearch": {
                    "vector": {"value": embedding, "path": "embedding", "k": k}
                }
            }
        },
        {"$limit": k},
    ]
    if projection:
        pipeline.append({"$project": projection})
    cursor = coll.aggregate(pipeline)
    results = []
    for doc in cursor:
        # DocumentDB may include a searchScore field depending on projection; include raw doc
        results.append(doc)
    return results
"}

