import os

app = FastAPI()

class PatientFeatures(BaseModel):
    features: dict

@app.post('/predict')
def predict(payload: PatientFeatures):
    features = payload.features
    text_repr = " ".join(f"{k}:{v}" for k, v in features.items())
    try:
        emb = embed_text(text_repr)[0]
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    results = vector_search(emb, k=int(os.environ.get('TOP_K',5)))
    narrative = generate_narrative(features, results)
    return {"narrative": narrative, "matches": results}
"}

