def features_to_text(features: dict) -> str:
    # deterministic string representation
    parts = []
    for k in sorted(features.keys()):
        v = features[k]
        parts.append(f"{k}:{v}")
    return "; ".join(parts)


def get_embedding_for_features(features: dict):
