    """Compatibility wrapper: takes str or list[str] and returns list of embedding vectors."""
    if not OPENAI_API_KEY:
        raise RuntimeError("OPENAI_API_KEY not set; cannot compute embeddings")
    if isinstance(texts, str):
        texts = [texts]
    resp = openai.Embedding.create(model=EMBEDDING_MODEL, input=texts)
    return [item['embedding'] for item in resp['data']]
