import os
import math

COLLECTION_NAME = os.environ.get("COLLECTION_NAME","high_risk_profiles")


def _cosine_sim(a, b):
    # assume same length
    dot = sum(x*y for x,y in zip(a,b))
    na = math.sqrt(sum(x*x for x in a))
    nb = math.sqrt(sum(x*x for x in b))
    if na==0 or nb==0:
        return 0.0
    return dot/(na*nb)


def vector_search(embedding, k=5, projection=None):
    """Run a server-side vector search using DocumentDB $search / cosmosSearch operator.
    If $search is not available (e.g., mongomock), fall back to client-side linear scan and cosine similarity.
    Returns list of docs (may include score under '_score').
    """
    db = get_db()
    coll = db[COLLECTION_NAME]
    pipeline = [
        {
            "$search": {
